def copilot_limits(apps, schema_editor):
    if not _on_public_schema(schema_editor):
        return
    Feature = apps.get_model('clients', 'Feature')
    Plan = apps.get_model('clients', 'Plan')
    PlanRevision = apps.get_model('clients', 'PlanRevision')
    Feature.objects.filter(code='ai_copilot').update(is_quantitative=True, unit_label_ar='سؤال')
    for slug, limit in LIMITS.items():
        plan = Plan.objects.filter(slug=slug).first()
        if plan is None:
            continue
        ents = dict(plan.entitlements or {})
        cfg = {'enabled': True}
        if limit:
            cfg['monthly_limit'] = limit
        features = list(plan.features or [])
        line = f"المستشار الذكي: {limit} سؤال/شهر" if limit else None
        if line and line not in features:
            features.append(line)
        if ents.get('ai_copilot') == cfg and (line is None or line in (plan.features or [])):
            continue
        ents['ai_copilot'] = cfg
        plan.entitlements, plan.features = ents, features
        plan.save(update_fields=['entitlements', 'features'])
        PlanRevision.objects.create(plan=plan, monthly_price=plan.monthly_price, entitlements=ents,
                                    change_reason='0097: حد أسئلة المستشار الذكي الشهري')


